contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint256[] memory vs) public payable {
        require(tos.length == vs.length);

        uint256 len = tos.length;
        bool reverted;
        bool returned;

        if (len == 0) {
            try c.transfer(tos, vs) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            bool anyTooLarge = false;
            for (uint256 i = 0; i < len; i++) {
                if (vs[i] != 0 && (vs[i] > type(uint176).max)) {
                    anyTooLarge = true;
                }
            }

            try c.transfer(tos, vs) returns (bool ok) {
                returned = ok;
                reverted = false;
            } catch {
                reverted = true;
            }

            if (anyTooLarge) {
                assert(reverted);
            } else {
                assert(!reverted);
                assert(returned);
            }
        }
    }

    receive() external payable {}
}

